Given two arrays a[] and b[] of size n (each containing distinct integers, but possibly sharing some), construct an array res[] of size n that contains the largest n unique values from both arrays combined, where elements taken from a[] appear first in their original order, followed by elements from b[] in their original order, and no value appears more than once.Examples:Input: a[] = [9, 7, 2, 3, 6], b[] = [7, 4, 8, 0, 1]Output: [9, 7, 6, 4, 8]Explanation: Largest 5 unique elements from both arrays: {9, 8, 7, 6, 4}.From a[], take elements in order that are in top 5: 9, 7, 6.From b[], take remaining top elements: 4, 8.Resulting array: [9, 7, 6, 4, 8].Input: a[] = [6, 7, 5, 3], b[] = [5, 6, 2, 9]Output: [6, 7, 5, 9]Explanation: Largest 4 unique elements from both arrays: {9, 7, 6, 5}.From a[], take elements in order: 6, 7, 5.From b[], add remaining top element: 9.Resulting array: [6, 7, 5, 9].[Approach] Using Set - O(n log(n)) Time and O(n) SpaceWe can use a set (or similar data structure) that always maintains the n largest unique elements while scanning both arrays. As we insert elements from a[] and then b[], remove the smallest whenever the set size exceeds n. After processing both arrays, this set represents the final chosen values.To build the result, traverse a[] first and pick the elements that appear in the set, then traverse b[] for the remaining ones. This keeps the largest possible n values and preserves the required order: elements from a[] first, followed by elements from b[].
            C++

    //Driver Code Starts
#include <iostream>
#include <set>
#include <vector>
using namespace std;

//Driver Code Ends

vector<int> makelargest(vector<int> &a, vector<int> &b) {
    int n = a.size();
    set<int> se;

    // insert from a and keep only largest n elements
    for (int i = 0; i < n; i++) {
        se.insert(a[i]);
        if (se.size() > n) se.erase(se.begin());
    }

    // insert from b and keep only largest n elements
    for (int i = 0; i < n; i++) {
        se.insert(b[i]);
        if (se.size() > n) se.erase(se.begin());
    }

    vector<int> ans;

    // pick elements from a in original order
    for (int i = 0; i < n; i++) {
        auto it = se.find(a[i]);
        if (it != se.end()) {
            ans.push_back(a[i]);
            se.erase(it);
        }
    }

    // pick elements from b in original order
    for (int i = 0; i < n; i++) {
        auto it = se.find(b[i]);
        if (it != se.end()) {
            ans.push_back(b[i]);
            se.erase(it);
        }
    }

    return ans;
}

//Driver Code Starts

int main() {
    vector<int> a = {9, 7, 2, 3, 6};
    vector<int> b = {7, 4, 8, 0, 1};

    vector<int> ans = makelargest(a, b);

    for (int x : ans) cout << x << " ";
    return 0;
}

