import java.util.TreeSet;

class GFG {

//Driver Code Ends

    static ArrayList<Integer> makelargest(int[] a, int[] b) {

        int n = a.length;
        TreeSet<Integer> se = new TreeSet<>();

        // insert from a and keep largest n
        for (int i = 0; i < n; i++) {
            se.add(a[i]);
            if (se.size() > n) se.pollFirst();
        }

        // insert from b and keep largest n
        for (int i = 0; i < n; i++) {
            se.add(b[i]);
            if (se.size() > n) se.pollFirst();
        }

        ArrayList<Integer> ans = new ArrayList<>();

        // pick elements from a in original order
        for (int i = 0; i < n; i++) {
            if (se.contains(a[i])) {
                ans.add(a[i]);
                se.remove(a[i]);
            }
        }

        // pick elements from b in original order
        for (int i = 0; i < n; i++) {
            if (se.contains(b[i])) {
                ans.add(b[i]);
                se.remove(b[i]);
            }
        }

        return ans;
    }

